<?php
require_once __DIR__ . '/config.php'; require_once __DIR__ . '/includes/role_check.php'; require_once __DIR__ . '/includes/notification_helper.php'; require_role(['officer']);
$officer_id=(int)$_SESSION['user_id']; $message='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['update_case'])){
  $id=(int)($_POST['complaint_id']??0); $new_status=$_POST['status']??''; $remarks=trim($_POST['officer_remarks']??'');
  if(in_array($new_status,['Pending','In Progress','Resolved','Rejected'],true)){
    $q=$conn->prepare('SELECT c.*,u.full_name AS user_name FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.id=? AND c.officer_id=?'); $q->bind_param('ii',$id,$officer_id); $q->execute(); $old=$q->get_result()->fetch_assoc(); $q->close();
    if($old){$resolved=$new_status==='Resolved'?'NOW()':'NULL'; $stmt=$conn->prepare("UPDATE complaints SET status=?,officer_remarks=?,resolved_at=$resolved WHERE id=? AND officer_id=?"); $stmt->bind_param('ssii',$new_status,$remarks,$id,$officer_id); $stmt->execute(); $stmt->close(); $actor=$officer_id; $action='Status Updated'; $desc=$remarks!==''?$remarks:'Officer updated complaint progress.'; $tl=$conn->prepare('INSERT INTO complaint_timeline (complaint_id,user_id,action,old_value,new_value,description) VALUES (?,?,?,?,?,?)'); $tl->bind_param('iissss',$id,$actor,$action,$old['status'],$new_status,$desc); $tl->execute(); $tl->close(); notify_complaint_status_change($conn, $id, $old['status'], $new_status, $remarks); $message='Complaint updated and the complainant was notified.';}
  }
}
$status=$_GET['status']??''; $search=trim($_GET['search']??''); $sql='SELECT c.*,u.full_name AS user_name,u.email AS user_email,d.name AS department_name FROM complaints c JOIN users u ON u.id=c.user_id LEFT JOIN departments d ON d.id=c.department_id WHERE c.officer_id=?'; $types='i';$params=[$officer_id]; if(in_array($status,['Pending','In Progress','Resolved','Rejected'],true)){$sql.=' AND c.status=?';$types.='s';$params[]=$status;} if($search!==''){$sql.=' AND (c.subject LIKE ? OR c.description LIKE ?)';$types.='ss';$like="%$search%";$params[]=$like;$params[]=$like;} $sql.=' ORDER BY c.created_at DESC';$stmt=$conn->prepare($sql);$stmt->bind_param($types,...$params);$stmt->execute();$cases=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();$stats=[];$s=$conn->prepare('SELECT status,COUNT(*) total FROM complaints WHERE officer_id=? GROUP BY status');$s->bind_param('i',$officer_id);$s->execute();foreach($s->get_result() as $r)$stats[$r['status']]=(int)$r['total'];$s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Officer Dashboard | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php';?><main class="flex-grow-1"><header class="bg-white border-bottom p-3 d-flex justify-content-between"><div><h4 class="mb-0">Complaint Officer Dashboard</h4><small class="text-muted">Assigned investigations and resolution queue</small></div><span class="text-muted"><i class="bi bi-person-badge me-1"></i><?=htmlspecialchars($_SESSION['user_name'])?></span></header><div class="container-fluid p-4"><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><div class="row g-3 mb-4"><?php foreach([['Pending','warning','bi-hourglass-split'],['In Progress','info','bi-search'],['Resolved','success','bi-check-circle'],['Rejected','danger','bi-x-circle']] as $card):?><div class="col-6 col-xl-3"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between"><span class="text-muted"><?=$card[0]?></span><i class="bi <?=$card[2]?> text-<?=$card[1]?>"></i></div><h2 class="mt-2 mb-0"><?= $stats[$card[0]] ?? 0 ?></h2></div></div></div><?php endforeach;?></div><div class="card border-0 shadow-sm"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-8"><input class="form-control" name="search" value="<?=htmlspecialchars($search)?>" placeholder="Search assigned complaints"></div><div class="col-md-2"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Pending','In Progress','Resolved','Rejected'] as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Complaint</th><th>Complainant</th><th>Priority</th><th>Status</th><th>Progress</th></tr></thead><tbody><?php foreach($cases as $c):?><tr><td><a href="view_complaint.php?id=<?=$c['id']?>" class="fw-semibold text-decoration-none"><?=htmlspecialchars($c['subject'])?></a><div class="small text-muted">#<?=$c['id']?> · <?=htmlspecialchars($c['category'])?></div></td><td><?=htmlspecialchars($c['user_name'])?><div class="small text-muted"><?=htmlspecialchars($c['user_email'])?></div></td><td><span class="badge text-bg-<?=priority_badge_class($c['priority'])?>"><?=$c['priority']?></span></td><td><span class="badge text-bg-<?=status_badge_class($c['status'])?>"><?=$c['status']?></span></td><td><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#case<?=$c['id']?>"><i class="bi bi-pencil-square me-1"></i>Update</button><div class="modal fade" id="case<?=$c['id']?>" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h5 class="modal-title">Update complaint #<?=$c['id']?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="complaint_id" value="<?=$c['id']?>"><label class="form-label">Progress status</label><select class="form-select mb-3" name="status" required><?php foreach(['Pending','In Progress','Resolved','Rejected'] as $v):?><option <?=$c['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><label class="form-label">Investigation / resolution remarks</label><textarea class="form-control" name="officer_remarks" rows="4" placeholder="Record the action taken..."><?=htmlspecialchars($c['officer_remarks']??'')?></textarea></div><div class="modal-footer"><button class="btn btn-primary" name="update_case">Save progress</button></div></form></div></div></td></tr><?php endforeach;?><?php if(!$cases):?><tr><td colspan="5" class="text-center text-muted py-5">No complaints are currently assigned to you.</td></tr><?php endif;?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
